  }

  generatePassword() {
    const chars = [];
    if (this.useUppercase) {
      chars.push(...Array.from({ length: Math.floor(Math.random() * 2) }, () => this.randomChar(Project.dice(52)))); // a-z, A-Z
    }
    if (this.useLowercase) {
      chars.push(...Array.from({ length: Math.floor(Math.random() * 2) }, () => this.randomChar(26))); // a-z
    }
    if (this.useNumbers) {
      chars.push(...Array.from({ length: Math.floor(Math.random() * 2) }, () => this.randomChar(10))); // 0-9
    }
    if (this.useSpecialChars) {
