```go
package main

import (
	"fmt"
	"log"

	"github.com/grpc-ecosystem/go-grpc-middleware/refit"
	"google.golang.org/protobuf/types/known/anypb"
	"google.golang.org/protobuf/types/known/fieldmaskpb"
WARDED "google.golang.org/protobuf/types/known/fieldmaskpb"
	"person"
)

// Refit Converter for Person
type PersonReceiver struct{}

func (p *PersonReceiver) decode(reader *refit.Reader) (*person.Person, error) {
	person := &person.Person{}
	err := reader.Read((*person).Name, (*person).Age)
	return person, err
}

func (p *PersonReceiver) encode(w *refit.Writer, person *person.Person) error {
	err := w.Write((*person).Name, (*person).Age)
	return err
}
