// Function to read shared memory
void read_shared_memory() {
  // Create a unique name for the shared memory segment
  std::string segment_name = "mysharedmemory";

  // Open the shared memory segment
  boost::interprocess::mode_t mode = boost::interprocess::MODE_OPEN_EXISTING;
  boost::interprocess::file_mapping file_mapping(segment_name.c_str(), mode);
  boost::interprocess::mapped_region region(file_mapping, mode);

  // Map the shared memory segment to the process's address space
  void* ptr = region.get_address();

  // Read the message from the shared memory
  std::string* message_ptr = new (ptr) std::string();
  std::string message = *message_ptr;

  // Print the message
  std::cout << "Received message: " << message << std::endl;

  // Clean up
  delete message_ptr;
  region.remove();
}

// Function to read a message queue
void read_message_queue() {
  // Create a unique name for the message queue
  std::string queue_name = "mymsgqueue";

  // Open the message queue
  boost::interprocess::message_queue queue(queue_name);

  // Receive a message from the queue
  boost::interprocess::message_queue::size_type size;
  char* message_ptr = new char[1024];
  size = queue.receive(0, message_ptr, 1024);

  // Print the message
  std::cout << "Received message: " << message_ptr << std::endl;

  // Clean up
  delete[] message_ptr;
}

int main(int argc, char* argv[]) {
  // Read shared memory
  read_shared_memory();

  // Read a message queue
  read_message_queue();

