public class Sniffer {
  // Porta de escuta
  private static final int PORT = 1234;

  // Buffer para armazenar os pacotes
  private static final byte[] buffer = new byte[1500];

  public static void main(String[] args) throws Exception {
    // Cria um socket de escuta
    ServerSocketChannel ssc = ServerSocketChannel.open();
    ssc.socket().bind(new InetSocketAddress(PORT));
    ssc.configureBlocking(false);

    // Cria um buffer para armazenar os pacotes
    ByteBuffer buffer = ByteBuffer.wrap(buffer);

    // Loop para escutar pacotes
    while (true) {
      // Aguarda um pacote
      SocketChannel sc = ssc.accept();
      sc.configureBlocking(false);

      // Lê o pacote do buffer
      int bytesRead = sc.read(buffer);

      // Processa o pacote
      processPackage(buffer, bytesRead);

      // Fecha o socket
      sc.close();
    }
  }

  // Método para processar um pacote
  private static void processPackage(ByteBuffer buffer, int bytesRead) {
    // Extrai o protocolo do pacote (UDP ou TCP)
    int protocol = buffer.get(0);

    // Extrai a origem e destino do pacote
    byte[] srcMac = new byte[6];
    byte[] dstMac = new byte[6];
    bufferład(buffer, 1, srcMac, 0);
    bufferład(buffer, 7, dstMac, 0);
    String srcMacStr = Bytes.toHexString(srcMac);
    String dstMacStr = Bytes.toHexString(dstMac);

    // Extrai a porta de origem e destino do pacote
    int srcPort = buffer.getInt(12);
    int dstPort = buffer.getInt(16);

    // Impressa informações do pacote
    System.out.println("Protocolo: " + protocol);
    System.out.println("Origem: " + srcMacStr + ":" + srcPort);
    System.out.println("Destino: " + dstMacStr + ":" + dstPort);
    System.out.println("Bytes lidos: " + bytesRead);
  }
}

// Classe para trabalhar com bytes
public class Bytes {
  public static String toHexString(byte[] bytes) {
    StringBuilder sb = new StringBuilder();
    for (byte b : bytes) {
      sb.append(String.format("%02x", b));
    }
    return sb.toString();
  }

  public static void bufferład(ByteBuffer buffer, int offset, byte[] dst, int dstOffset) {
    buffer.get(dst, dstOffset, dst.length - dstOffset);
  }
}
