import axios from 'axios';

class SessionManager extends Component {
  constructor(props) {
    super(props);
    this.state = {
      isLoggedIn: false,
      user: null,
      token: null,
    };
  }

  async handleGoogleLogin() {
    window.location = `https://accounts.google.com/o/oauth2/v2/auth?client_id=${process.env.REACT_APP_GOOGLE_CLIENT_ID}&redirect_uri=http://localhost:3000/callback&response_type=token&scope=profile email`;
  }

  async handleCallback() {
    const token = new URLSearchParams(window.location.search).get('access_token');
    if (token) {
      try {
        const response = await axios.post('/api/auth', { token });
        this.setState({
          isLoggedIn: true,
          user: response.data.user,
          token: token,
        });
      } catch (error) {
        console.error(error);
      }
    }
  }

  async handleLogout() {
    this.setState({
      isLoggedIn: false,
      user: null,
      token: null,
    });
  }

  render() {
    if (!this.state.isLoggedIn) {
      return (
        <div>
          <button onClick={this.handleGoogleLogin}>Login with Google</button>
        </div>
      );
    }

    return (
      <div>
        <h1>Welcome, {this.state.user.name}!</h1>
        <button onClick={this.handleLogout}>Logout</button>
      </div>
    );
  }
}

export default SessionManager;
